from marshmallow import Schema, fields, validate, ValidationError

class NotificationPreferencesSchema(Schema):
    email = fields.Boolean()
    push = fields.Boolean()
    sms = fields.Boolean()

class UserPreferencesSchema(Schema):
    theme = fields.Str(
        validate=validate.OneOf(['light', 'dark', 'auto']),
        required=True
    )
    language = fields.Str(
        validate=validate.OneOf(['en', 'es', 'fr', 'de', 'ja', 'zh']),
        required=True
    )
    timezone = fields.Str(required=True)
    notifications = fields.Nested(NotificationPreferencesSchema, required=True)
    updated_at = fields.DateTime(dump_only=True)

class ErrorResponseSchema(Schema):
    error = fields.Str(required=True)
    message = fields.Str(required=True)
    status_code = fields.Int(required=True)
