from flask import Blueprint, jsonify, request
from app.auth import token_required
from app.models import db, User, UserPreferences
from app.schemas import UserPreferencesSchema, ErrorResponseSchema
from marshmallow import ValidationError

api = Blueprint('api', __name__)

preferences_schema = UserPreferencesSchema()
error_schema = ErrorResponseSchema()


@api.route('/api/user/preferences', methods=['GET'])
@token_required
def get_user_preferences(current_user_id):
    """
    Get user preference settings

    Returns:
        200: User preferences object
        401: Unauthorized (no valid token)
        404: User preferences not found
        500: Internal server error
    """
    try:
        # Get user
        user = User.query.get(current_user_id)

        if not user:
            return jsonify({
                'error': 'Not Found',
                'message': 'User not found',
                'status_code': 404
            }), 404

        # Get or create preferences
        preferences = UserPreferences.query.filter_by(user_id=current_user_id).first()

        if not preferences:
            # Create default preferences if they don't exist
            preferences = UserPreferences(user_id=current_user_id)
            db.session.add(preferences)
            db.session.commit()

        # Serialize and return
        result = preferences_schema.dump(preferences.to_dict())

        return jsonify({
            'success': True,
            'data': result
        }), 200

    except Exception as e:
        db.session.rollback()
        return jsonify({
            'error': 'Internal Server Error',
            'message': str(e),
            'status_code': 500
        }), 500


@api.route('/api/user/preferences', methods=['PUT'])
@token_required
def update_user_preferences(current_user_id):
    """
    Update user preference settings

    Request Body:
        {
            "theme": "dark",
            "language": "en",
            "timezone": "America/New_York",
            "notifications": {
                "email": true,
                "push": false,
                "sms": false
            }
        }

    Returns:
        200: Updated preferences
        400: Invalid request data
        401: Unauthorized
        500: Internal server error
    """
    try:
        # Validate request data
        data = request.get_json()

        if not data:
            return jsonify({
                'error': 'Bad Request',
                'message': 'No data provided',
                'status_code': 400
            }), 400

        try:
            validated_data = preferences_schema.load(data)
        except ValidationError as err:
            return jsonify({
                'error': 'Validation Error',
                'message': err.messages,
                'status_code': 400
            }), 400

        # Get or create preferences
        preferences = UserPreferences.query.filter_by(user_id=current_user_id).first()

        if not preferences:
            preferences = UserPreferences(user_id=current_user_id)
            db.session.add(preferences)

        # Update preferences
        preferences.theme = validated_data['theme']
        preferences.language = validated_data['language']
        preferences.timezone = validated_data['timezone']
        preferences.notifications = validated_data['notifications']

        db.session.commit()

        # Return updated preferences
        result = preferences_schema.dump(preferences.to_dict())

        return jsonify({
            'success': True,
            'data': result,
            'message': 'Preferences updated successfully'
        }), 200

    except Exception as e:
        db.session.rollback()
        return jsonify({
            'error': 'Internal Server Error',
            'message': str(e),
            'status_code': 500
        }), 500


@api.errorhandler(404)
def not_found(error):
    return jsonify({
        'error': 'Not Found',
        'message': 'The requested resource was not found',
        'status_code': 404
    }), 404


@api.errorhandler(500)
def internal_error(error):
    db.session.rollback()
    return jsonify({
        'error': 'Internal Server Error',
        'message': 'An unexpected error occurred',
        'status_code': 500
    }), 500
