import { ApiError, PreferencesError } from '../types/preferences';

interface RequestConfig extends RequestInit {
  requiresAuth?: boolean;
}

class ApiClient {
  private baseURL: string;
  private tokenKey: string;

  constructor(baseURL: string = 'http://localhost:5000', tokenKey: string = 'access_token') {
    this.baseURL = baseURL;
    this.tokenKey = tokenKey;
  }

  private getAuthToken(): string | null {
    return localStorage.getItem(this.tokenKey);
  }

  private getHeaders(requiresAuth: boolean = false): HeadersInit {
    const headers: HeadersInit = {
      'Content-Type': 'application/json',
    };

    if (requiresAuth) {
      const token = this.getAuthToken();
      if (token) {
        headers['Authorization'] = `Bearer ${token}`;
      }
    }

    return headers;
  }

  async request<T>(
    endpoint: string,
    config: RequestConfig = {}
  ): Promise<T> {
    const { requiresAuth = false, ...fetchConfig } = config;

    const url = `${this.baseURL}${endpoint}`;
    const headers = this.getHeaders(requiresAuth);

    try {
      const response = await fetch(url, {
        ...fetchConfig,
        headers: {
          ...headers,
          ...fetchConfig.headers,
        },
      });

      const data = await response.json();

      if (!response.ok) {
        const error = data as ApiError;
        throw new PreferencesError(
          typeof error.message === 'string' 
            ? error.message 
            : JSON.stringify(error.message),
          error.status_code,
          error.error
        );
      }

      return data as T;
    } catch (error) {
      if (error instanceof PreferencesError) {
        throw error;
      }

      // Network or other errors
      throw new PreferencesError(
        error instanceof Error ? error.message : 'An unexpected error occurred',
        500,
        'NetworkError'
      );
    }
  }

  async get<T>(endpoint: string, requiresAuth: boolean = false): Promise<T> {
    return this.request<T>(endpoint, {
      method: 'GET',
      requiresAuth,
    });
  }

  async post<T>(
    endpoint: string,
    body: unknown,
    requiresAuth: boolean = false
  ): Promise<T> {
    return this.request<T>(endpoint, {
      method: 'POST',
      body: JSON.stringify(body),
      requiresAuth,
    });
  }

  async put<T>(
    endpoint: string,
    body: unknown,
    requiresAuth: boolean = false
  ): Promise<T> {
    return this.request<T>(endpoint, {
      method: 'PUT',
      body: JSON.stringify(body),
      requiresAuth,
    });
  }

  async delete<T>(endpoint: string, requiresAuth: boolean = false): Promise<T> {
    return this.request<T>(endpoint, {
      method: 'DELETE',
      requiresAuth,
    });
  }
}

export const apiClient = new ApiClient();
