### 5. Preferences Service (`src/services/preferencesService.ts`)
```typescript
import { apiClient } from '../utils/apiClient';
import { UserPreferences, ApiResponse } from '../types/preferences';

export class PreferencesService {
  private static readonly ENDPOINT = '/api/user/preferences';

  /**
   * Get user preferences
   * @throws {PreferencesError} If the request fails
   */
  static async getPreferences(): Promise<UserPreferences> {
    const response = await apiClient.get<ApiResponse<UserPreferences>>(
      this.ENDPOINT,
      true
    );
    return response.data;
  }

  /**
   * Update user preferences
   * @param preferences - The preferences to update
   * @throws {PreferencesError} If the request fails
   */
  static async updatePreferences(
    preferences: UserPreferences
  ): Promise<UserPreferences> {
    const response = await apiClient.put<ApiResponse<UserPreferences>>(
      this.ENDPOINT,
      preferences,
      true
    );
    return response.data;
  }

  /**
   * Update a specific preference field
   * @param field - The field to update
   * @param value - The new value
   * @throws {PreferencesError} If the request fails
   */
  static async updatePreference<K extends keyof UserPreferences>(
    field: K,
    value: UserPreferences[K]
  ): Promise<UserPreferences> {
    const currentPreferences = await this.getPreferences();
    const updatedPreferences = {
      ...currentPreferences,
      [field]: value,
    };
    return this.updatePreferences(updatedPreferences);
  }
}
