### 6. React Hook (Optional) (`src/hooks/useUserPreferences.ts`)
```typescript
import { useState, useEffect, useCallback } from 'react';
import { UserPreferences, PreferencesError } from '../types/preferences';
import { PreferencesService } from '../services/preferencesService';

interface UseUserPreferencesReturn {
  preferences: UserPreferences | null;
  loading: boolean;
  error: PreferencesError | null;
  refetch: () => Promise<void>;
  updatePreferences: (preferences: UserPreferences) => Promise<void>;
  updatePreference: <K extends keyof UserPreferences>(
    field: K,
    value: UserPreferences[K]
  ) => Promise<void>;
}

export const useUserPreferences = (
  autoFetch: boolean = true
): UseUserPreferencesReturn => {
  const [preferences, setPreferences] = useState<UserPreferences | null>(null);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<PreferencesError | null>(null);

  const fetchPreferences = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const data = await PreferencesService.getPreferences();
      setPreferences(data);
    } catch (err) {
      if (err instanceof PreferencesError) {
        setError(err);
      } else {
        setError(
          new PreferencesError(
            'Failed to fetch preferences',
            500,
            'UnknownError'
          )
        );
      }
    } finally {
      setLoading(false);
    }
  }, []);

  const updatePreferences = useCallback(
    async (newPreferences: UserPreferences) => {
      setLoading(true);
      setError(null);

      try {
        const data = await PreferencesService.updatePreferences(newPreferences);
        setPreferences(data);
      } catch (err) {
        if (err instanceof PreferencesError) {
          setError(err);
        } else {
          setError(
            new PreferencesError(
              'Failed to update preferences',
              500,
              'UnknownError'
            )
          );
        }
        throw err;
      } finally {
        setLoading(false);
      }
    },
    []
  );

  const updatePreference = useCallback(
    async <K extends keyof UserPreferences>(
      field: K,
      value: UserPreferences[K]
    ) => {
      if (!preferences) {
        throw new Error('Preferences not loaded');
      }

      const updatedPreferences = {
        ...preferences,
        [field]: value,
      };

      await updatePreferences(updatedPreferences);
    },
    [preferences, updatePreferences]
  );

  useEffect(() => {
    if (autoFetch) {
      fetchPreferences();
    }
  }, [autoFetch, fetchPreferences]);

  return {
    preferences,
    loading,
    error,
    refetch: fetchPreferences,
    updatePreferences,
    updatePreference,
  };
};
```

