import React from 'react';
import { useUserPreferences } from './hooks/useUserPreferences';
import { Theme } from './types/preferences';

export const UserPreferencesComponent: React.FC = () => {
  const {
    preferences,
    loading,
    error,
    updatePreference,
  } = useUserPreferences();

  if (loading) {
    return <div>Loading preferences...</div>;
  }

  if (error) {
    return (
      <div className="error">
        <h3>Error: {error.error}</h3>
        <p>{error.message}</p>
      </div>
    );
  }

  if (!preferences) {
    return <div>No preferences found</div>;
  }

  const handleThemeChange = async (theme: Theme) => {
    try {
      await updatePreference('theme', theme);
    } catch (err) {
      console.error('Failed to update theme:', err);
    }
  };

  return (
    <div className="preferences-container">
      <h2>User Preferences</h2>

      <div className="preference-item">
        <label>Theme:</label>
        <select
          value={preferences.theme}
          onChange={(e) => handleThemeChange(e.target.value as Theme)}
        >
          <option value="light">Light</option>
          <option value="dark">Dark</option>
          <option value="auto">Auto</option>
        </select>
      </div>

      <div className="preference-item">
        <label>Language:</label>
        <span>{preferences.language}</span>
      </div>

      <div className="preference-item">
        <label>Timezone:</label>
        <span>{preferences.timezone}</span>
      </div>

      <div className="preference-item">
        <label>Notifications:</label>
        <ul>
          <li>Email: {preferences.notifications.email ? 'On' : 'Off'}</li>
          <li>Push: {preferences.notifications.push ? 'On' : 'Off'}</li>
          <li>SMS: {preferences.notifications.sms ? 'On' : 'Off'}</li>
        </ul>
      </div>
    </div>
  );
};
